package examples

import (
	"context"
	"os"

	"github.com/hetznercloud/hcloud-go/v2/hcloud"
)

func main() {
	token := os.Getenv("HCLOUD_TOKEN")

	client := hcloud.NewClient(hcloud.WithToken(token))
	ctx := context.TODO()

	result, _, err := client.Server.Create(ctx, hcloud.ServerCreateOpts{
		Automount: hcloud.Ptr(false),
		Firewalls: []*hcloud.ServerCreateFirewall{
			{
				Firewall: hcloud.Firewall{ID: 38},
			},
		},
		Image: &hcloud.Image{Name: "ubuntu-24.04"},
		Labels: map[string]string{
			"environment":    "prod",
			"example.com/my": "label",
			"just-a-key":     "",
		},
		Location: &hcloud.Location{Name: "nbg1"},
		Name:     "my-server",
		Networks: []*hcloud.Network{
			{
				ID: 456,
			},
		},
		PlacementGroup: &hcloud.PlacementGroup{ID: 1},
		PublicNet: &hcloud.ServerCreatePublicNet{
			EnableIPv4: false,
			EnableIPv6: false,
			IPv4:       nil,
			IPv6:       nil,
		},
		ServerType: &hcloud.ServerType{Name: "cx23"},
		SSHKeys: []*hcloud.SSHKey{
			{
				Name: "my-ssh-key",
			},
		},
		StartAfterCreate: hcloud.Ptr(true),
		UserData:         "#cloud-config\nruncmd:\n- [touch, /root/cloud-init-worked]\n",
		Volumes: []*hcloud.Volume{
			{
				ID: 123,
			},
		},
	})

	err = client.Action.WaitFor(ctx, result.Action)

	server := result.Server
}

